export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed;
  const g = inputs.gravity;
  const m = inputs.mass;

  const tApex = u / g;
  const yApex = (u * u) / (2 * g);
  const tEnd = (2 * u) / g;
  const tClamped = Math.max(0, Math.min(tEnd, time));

  const v = u - g * tClamped;
  const y = u * tClamped - 0.5 * g * tClamped * tClamped;
  const a = -g;
  const F = m * g;

  let motionState = "At the top";
  if (tClamped === 0) {
    motionState = "Ready to toss";
  } else if (Math.abs(tClamped - tApex) < 0.02) {
    motionState = "At the top";
  } else if (tClamped < tApex) {
    motionState = "Rising";
  } else if (tClamped < tEnd - 0.005) {
    motionState = "Falling";
  } else {
    motionState = "Back at launch height";
  }

  const objects = [];

  // Panel 1: Motion Lane
  const lane1 = sdk.panel({ x: 20, y: 30, w: 290, h: 370, title: "The motion", state: motionState, id: "lane.toss" });
  objects.push(...lane1);

  const axisY = sdk.axis("axis.height", {
    x: 75,
    y: 360,
    length: 290,
    orientation: "y",
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height",
    unit: "m"
  });
  objects.push(axisY);

  const ballPxX = 140;
  const ballPxY = 360 - (y / 2.2) * 290;

  const ball = sdk.circle("ball.toss", ballPxX, ballPxY, 24);
  objects.push(ball);

  const vecV = sdk.vector("vec.v", { x: ballPxX, y: ballPxY }, {
    value: v,
    direction: "up",
    scale: 15,
    label: "v"
  });
  objects.push(...vecV);

  const vecA = sdk.vector("vec.a", { x: ballPxX + 35, y: ballPxY }, {
    value: a,
    direction: "up",
    scale: 6,
    label: "a"
  });
  objects.push(...vecA);

  const calloutLines = [
    `v: ${sdk.format(v, 2)} m/s`,
    `a: ${sdk.format(a, 2)} m/s²`,
    `Fg: ${sdk.format(F, 1)} N`
  ];
  const callout = sdk.callout(ballPxX + 55, ballPxY - 20, calloutLines, { id: "callout.toss" });
  objects.push(...callout);

  // Panel 2: Velocity-Time Graph Lane
  const lane2 = sdk.panel({ x: 330, y: 30, w: 290, h: 370, title: "Velocity over time", state: `a = -${sdk.format(g, 1)} m/s²`, id: "lane.plot" });
  objects.push(...lane2);

  const ptsFaint = [];
  const ptsTrace = [];
  const nSamples = 24;
  for (let i = 0; i <= nSamples; i++) {
    const st = (tEnd * i) / nSamples;
    const sv = u - g * st;
    ptsFaint.push({ x: st, y: sv });
    if (st <= tClamped + 1e-4) {
      ptsTrace.push({ x: st, y: sv });
    }
  }
  if (ptsTrace.length > 0 && Math.abs(ptsTrace[ptsTrace.length - 1].x - tClamped) > 1e-4) {
    ptsTrace.push({ x: tClamped, y: v });
  }

  const plotVt = sdk.plot("plot.vt", {
    x: 350,
    y: 70,
    w: 250,
    h: 300,
    axes: {
      x: { label: "Time", min: 0, max: 1.8, unit: "s" },
      y: { label: "Velocity", min: -5.5, max: 5.5, unit: "m/s" }
    },
    series: [
      { label: "Faint continuation", kind: "line", points: ptsFaint },
      { label: "Current trajectory", kind: "line", points: ptsTrace }
    ]
  });
  objects.push(plotVt);

  return {
    frame: sdk.frame(objects, { width: 640, height: 420 }),
    quantities: {
      launchSpeed: u,
      gravity: g,
      mass: m,
      apexTime: tApex,
      apexHeight: yApex,
      height: y,
      velocity: v,
      acceleration: a,
      force: F
    },
    readouts: [
      { id: "velocity", value: v },
      { id: "acceleration", value: a },
      { id: "force", value: F },
      { id: "motionState", value: motionState }
    ]
  };
}
